def S(pid, lead, pri, old, new, lang, ctype, basis, reason, down="Regenerate every listed Master cell; page_specs.json; search_index.json; dist EN/AR",
      search="Index text updates on regeneration", ia="none", vis="none", rights="none", val=None, sheets=None, rows=None, fields=None,
      expect=None, sem="yes", status="SPEC_PENDING_EXECUTION"):
    return dict(pid=pid, lead=lead, pri=pri, op="SUBSTR", old=old, new=new, lang=lang, ctype=ctype, basis=basis, reason=reason,
                down=down, search=search, ia=ia, vis=vis, rights=rights,
                val=val or "After regeneration the old string occurs 0 times in Master, projections and dist; the new string renders on every listed surface; public-literal closure passes.",
                sheets=sheets, rows=rows, fields=fields, expect=expect, sem=sem, status=status)

def C(pid, lead, pri, sheet, obj, field, cur, new, lang, ctype, basis, reason, down, val, sem="yes", op="CELL", search="none", ia="none", vis="none", rights="none", status="SPEC_PENDING_EXECUTION"):
    return dict(pid=pid, lead=lead, pri=pri, op=op, sheet=sheet, obj=obj, field=field, cur=cur, new=new, lang=lang, ctype=ctype,
                basis=basis, reason=reason, down=down, search=search, ia=ia, vis=vis, rights=rights, val=val, sem=sem, status=status)

